import http from 'k6/http';
import { check, sleep } from 'k6';

export let options = {
  stages: [
    { duration: '15m', target: 1000 },
    { duration: '2h', target: 8000 },
    { duration: '15m', target: 0 }
  ],
  thresholds: {
    http_req_duration: ['p(99.9)<500'],
    http_req_failed: ['rate<0.01']
  }
};

export default function () {
  const cacheHit = Math.random() < 0.6;
  const path = cacheHit 
    ? `/api/thumbnails/cached/${Math.floor(Math.random() * 10000)}`
    : `/api/thumbnails/generate/${Math.floor(Math.random() * 10000)}`;

  const res = http.get(`https://edge.example.com${path}`);
  check(res, { 'status is 200': (r) => r.status === 200 });
  sleep(Math.random() * 2);
}
```

